pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 value) public {
        // Ensure value is valid for call
        vm.assume(adr != address(0));
        // Record the original Owner
        address originalOwner = c.Owner();
        // Make a prank call as some random user (not Owner)
        address randomUser = address(0x1234);
        vm.deal(randomUser, value);
        vm.prank(randomUser);
        // Call Command - this will revert in reference if not Owner, succeed in mutant
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.Command.selector, adr, data));
        // If the call succeeded (mutant case), the Owner must still be the original
        if (success) {
            assertTrue(c.Owner() == originalOwner, "Owner unchanged after Command call by non-owner");
        } else {
            // If reverted (reference behavior), no state change possible
            assertTrue(true); // just pass
        }
    }
}

