pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address payable adr, uint256 contractBalance, uint256 sendAmount) public {
        // Ensure the reference works: msg.value >= address(this).balance
        vm.assume(contractBalance <= type(uint256).max / 2);
        vm.assume(sendAmount >= contractBalance);
        vm.assume(sendAmount <= type(uint256).max - contractBalance);
        vm.assume(adr != address(0));

        // Fund the contract
        vm.deal(address(c), contractBalance);

        // Get balance of adr before
        uint256 before = adr.balance;

        // Call Command as owner to seed multiplicate call
        // Command calls multiplicate via the data
        bytes memory data = abi.encodeWithSignature("multiplicate(address)", adr);
        vm.prank(c.Owner());
        c.Command{value: sendAmount}(address(c), data);

        // Get balance of adr after
        uint256 after = adr.balance;

        // The rule: adr must have received (contractBalance + sendAmount), because the reference transfers total balance
        // The bug sends only msg.value, so the difference is contractBalance
        assertTrue(after - before == contractBalance + sendAmount, "Should transfer total balance");
    }
}

