pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 msgValue, uint256 initialBalance) public {
        vm.assume(adr != address(0) && adr != address(c));
        initialBalance = bound(initialBalance, 0, 100 ether);
        msgValue = bound(msgValue, 0, 100 ether);
        // Ensure msg.value >= contract balance so the if branch is taken
        vm.assume(msgValue >= initialBalance);
        vm.deal(address(c), initialBalance);
        uint256 callerBalanceBefore = address(this).balance;
        bytes memory emptyData = "";
        // Fund caller
        vm.deal(address(this), msgValue + 1 ether);
        c.Command{value: msgValue}(adr, emptyData);
        uint256 callerBalanceAfter = address(this).balance;
        // The reference C sends address(this).balance + msg.value (i.e., initialBalance + msgValue) to adr.
        // The buggy version sends only msg.value.
        // The caller's balance decrease is msg.value in both cases.
        // But the contract's final balance differs.
        // Rule: after the call, the caller's balance decreased by exactly msg.value (the amount sent)
        assertTrue(callerBalanceAfter == callerBalanceBefore - msgValue);
    }
}

