contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, uint256 value, uint256 dataLength) public {
        vm.assume(adr != address(0) && adr != address(c));
        vm.assume(dataLength <= 1024);

        // Set contract balance high enough by sending value to receive()
        vm.deal(address(c), 1 ether);

        // Ensure msg.value >= contract balance (1 ether)
        vm.assume(value >= 1 ether);

        // Call Command to trigger the deposit
        bytes memory data = new bytes(dataLength);
        c.Command{value: value}(adr, data);

        uint256 balBefore = address(c).balance;

        // Now call multiplicate with 0 value — should not trigger if(msg.value>=balance) because 0 < any positive balance
        c.multiplicate{value: 0}(adr);

        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore, "multiplicate with 0 value should not change balance");
    }
}

