        vm.deal(address(c), initialBalance);
        uint256 preBalance = address(c).balance;
        if (value <= address(c).balance) {
            uint256 postBalance = address(c).balance;
            // The bug (<=) will transfer out when value <= balance, reducing balance.
            // The reference (>=) only transfers when value >= balance.
            // For value > balance, no transfer happens in either version.
            assertTrue(false, "This assertion is not reached; see below");
        }
        vm.assume(value <= address(c).balance);
        c.Command{value: value}(adr, data);
        uint256 postBalance = address(c).balance;
        assertTrue(postBalance >= preBalance);
    }
}

