pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address target, bytes memory data, uint256 value) public {
        // Restrict: caller is the owner so Command can proceed
        vm.assume(caller == c.Owner());
        // Bound value to reasonable range
        value = bound(value, 0, 100 ether);

        // Deal ether to caller for possible msg.value
        vm.deal(caller, value);
        vm.prank(caller);

        // Call Command with the given parameters
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.Command.selector, target, data));

        // After Command, measure the contract balance
        uint256 balance = address(c).balance;

        // The general rule: after Command, whenever msg.value >= balance, 
        // multiplicate would transfer at most balance (i.e., the condition 
        // msg.value >= balance should lead to a require that reverts or transfers all). 
        // In the reference, the require is true only if balance + msg.value >= balance,
        // which is always true, so multiplicate would send all. 
        // In the mutant, require(false) means multiplicate always reverts, 
        // so the invariant "balance is at least what multiplicate would send" breaks.
        assertTrue(balance >= (msg.value >= balance ? balance + msg.value : 0));
    }
}

